import{_ as t,o as a,c as o,a0 as r}from"./chunks/framework.D4fUSYzX.js";const p=JSON.parse('{"title":"The quality gate","description":"The two loops a change runs through, the rules a review measures, and what the gate does not claim.","frontmatter":{"title":"The quality gate","description":"The two loops a change runs through, the rules a review measures, and what the gate does not claim."},"headers":[],"relativePath":"development/quality-gate.md","filePath":"development/quality-gate.md"}'),s={name:"development/quality-gate.md"};function n(i,e,d,h,c,l){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="the-quality-gate" tabindex="-1">The quality gate <a class="header-anchor" href="#the-quality-gate" aria-label="Permalink to &quot;The quality gate&quot;">​</a></h1><p>This page states how a change is checked, and what a claim about a check has to carry. <a href="./../adr/0105-the-push-gate-runs-the-three-checks-on-the-merged-tree-and-a-hook-owns-the-two-cheap-ones.html">ADR 0105</a> records the decision. The rules below are the ones the reviews of pull requests #222, #224, #227, #229, #233, and #300 had to ask for by hand.</p><h2 id="two-loops" tabindex="-1">Two loops <a class="header-anchor" href="#two-loops" aria-label="Permalink to &quot;Two loops&quot;">​</a></h2><p>The inner loop runs while the work runs. It is small on purpose: the full suite after every edit is the cost that makes an agent skip a check.</p><table tabindex="0"><thead><tr><th>Command</th><th>What it covers</th><th>Measured cost</th></tr></thead><tbody><tr><td><code>bun run fmt</code>, or <code>bun run lint</code> on the files you touched</td><td>Format and lint with Biome</td><td>0.25 s over 296 files</td></tr><tr><td><code>bun run typecheck</code></td><td>TypeScript over <code>src</code> and <code>test</code></td><td>2.8 s</td></tr><tr><td><code>bun test &lt;file&gt;</code></td><td>The suite of the file you changed</td><td>1.7 s for 124 tests</td></tr><tr><td><code>bun run test:changed</code></td><td>The test files the current changes can affect</td><td>near zero when nothing changed</td></tr></tbody></table><p>The whole loop costs about 5 seconds. <code>bun run test</code> does not belong in it.</p><h2 id="the-push-gate" tabindex="-1">The push gate <a class="header-anchor" href="#the-push-gate" aria-label="Permalink to &quot;The push gate&quot;">​</a></h2><p>Exactly one full <code>bun run test</code> gates the push, and it runs against the merged tree, in this order:</p><ol><li>Rebase onto <code>origin/main</code>.</li><li>Check that a new ADR number is still free on the merged tree.</li><li><code>bun run lint</code>.</li><li><code>bun run typecheck</code>.</li><li><code>bun run test</code>, once.</li><li><code>bun run docs:build</code>, when the change touches <code>docs/</code>, <code>CONTEXT.md</code>, or an ADR. CI runs the same build and blocks on it.</li></ol><p>A branch that falls behind <code>origin/main</code> again during a rework round rebases and runs the gate again. A suite result measured on a tree that is not the tree that merges says nothing about the tree that merges.</p><p><code>bun run mutate</code> stays outside the gate: a campaign costs hours (<a href="./../adr/0055-mutation-testing-runs-on-the-bun-test-runner.html">ADR 0055</a>).</p><h2 id="the-hook" tabindex="-1">The hook <a class="header-anchor" href="#the-hook" aria-label="Permalink to &quot;The hook&quot;">​</a></h2><p><code>scripts/git-hooks/pre-push</code> runs <code>bun run lint</code> and <code>bun run typecheck</code>, and refuses a push whose branch is behind its remote-tracking branch. It reads the ref the checkout already holds and fetches nothing.</p><p>A committed hook is not active by itself. It runs in a checkout that has set it:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> core.hooksPath</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/git-hooks</span></span></code></pre></div><p>Do not bypass it with <code>--no-verify</code>. CI runs the same checks, and a bypass only moves the failure to a red check on the pull request.</p><h2 id="a-claim-a-document-makes-is-a-claim-the-code-keeps" tabindex="-1">A claim a document makes is a claim the code keeps <a class="header-anchor" href="#a-claim-a-document-makes-is-a-claim-the-code-keeps" aria-label="Permalink to &quot;A claim a document makes is a claim the code keeps&quot;">​</a></h2><p>Every sentence written into <code>docs/</code>, <code>CONTEXT.md</code>, an ADR, or a module header that states behavior is re-read against the code path that produces that behavior before the push. The reviews found the same finding on four of the six pull requests: a page that says the header shrinks the mode cell first when the code gives up the seat reading first, a header comment that stated a record field backwards, a glossary entry that read as a pass through a standing row, an operator page that promised a rule the write-back does not follow.</p><p>A rename sweeps the old name. <code>docs/</code>, <code>CONTEXT.md</code>, the ADRs, and the verification records are searched for the name that left the tree, and each hit is updated or keeps the old name beside the probe it was measured under. Two reviews found a verification record and the module map naming a name the branch had already renamed.</p><p>A documented user-visible string has a test that reads it back: a record line, a Message line, a config key, and the level or kind the reference states beside it. <code>test/record-lines-doc.test.ts</code> is the pattern: it holds the configuration reference&#39;s literal lines to the source that writes them. A documented line with no test is how a record drifts, and a documented level no fake can tell apart is the same drift one level down.</p><h2 id="what-a-check-holds" tabindex="-1">What a check holds <a class="header-anchor" href="#what-a-check-holds" aria-label="Permalink to &quot;What a check holds&quot;">​</a></h2><p>Three checks read the repository&#39;s own prose and sources and refuse the drift a review would otherwise have to find:</p><table tabindex="0"><thead><tr><th>Check</th><th>What it refuses</th></tr></thead><tbody><tr><td><code>test/record-lines-doc.test.ts</code></td><td>a record line the configuration reference states that the code does not write, and a level the page states that the code does not send</td></tr><tr><td><code>test/shape-doc-paths.test.ts</code></td><td>a path <code>docs/agents/shape.md</code> prints that the tree does not hold, resolved against the entry that printed it</td></tr><tr><td><code>test/domain-export-architecture.test.ts</code></td><td>a <code>src/domain/</code> value export neither <code>src</code> nor a test asks for; a domain export that is a pure alias of another export of its own module; and a new domain type that neither side names, against a baseline that can only shrink</td></tr></tbody></table><p>The second rule is the one the #223 review found standing in that directory: <code>topUpCycleOpen</code> was a wrapper of <code>freshWorkHold</code> with no <code>src</code> caller and nine test callers, and a rule that only asks &quot;does anything read this?&quot; cannot see it. The alias rule asks the shape instead, and it does not care whether it has readers.</p><h2 id="a-probe-is-a-step-a-reviewer-can-re-run" tabindex="-1">A probe is a step a reviewer can re-run <a class="header-anchor" href="#a-probe-is-a-step-a-reviewer-can-re-run" aria-label="Permalink to &quot;A probe is a step a reviewer can re-run&quot;">​</a></h2><p>When a change claims its test bites, the claim is written as steps in the test header: what to change in the source, which records go red, and how many. Every probe is re-run on the head that is pushed, and the counts are reported there.</p><p>#233 shows why the written form is required. Its first review found two probes no reviewer could re-run; its second review found one of the two did not reproduce as written, because the text named a line inside a shared helper instead of the record it meant. The rework re-ran all five probes and reported each count.</p><p>A new pure rule module under <code>src/domain/</code>, or a rewrite of one, gets a scoped mutation campaign, and the record names its scope and its score. For other work a written probe set is enough.</p><h2 id="a-test-does-not-stand-on-wall-clock-time" tabindex="-1">A test does not stand on wall-clock time <a class="header-anchor" href="#a-test-does-not-stand-on-wall-clock-time" aria-label="Permalink to &quot;A test does not stand on wall-clock time&quot;">​</a></h2><p>A test that reads real time, or that depends on a millisecond boundary, is rewritten to drive the rig&#39;s pinned clock. A new timing test passes 10 consecutive targeted runs before the push.</p><p>The load-flake rule stands as it is: a file that fails in the full suite and passes alone is a load flake, the report names it as one, and the machine&#39;s load is recorded beside it. The gate does not fix the CI frame-test flake; that item stays open in <a href="https://github.com/SeriousJul/my-little-software-factory/blob/main/docs/verification/quality-gate.md" target="_blank" rel="noreferrer">the verification record</a>.</p><h2 id="a-fake-carries-every-field-of-the-seam-it-stands-for" tabindex="-1">A fake carries every field of the seam it stands for <a class="header-anchor" href="#a-fake-carries-every-field-of-the-seam-it-stands-for" aria-label="Permalink to &quot;A fake carries every field of the seam it stands for&quot;">​</a></h2><p>A test fake that drops a field makes the documented property untestable. The shared record fake threw the log level away, so <code>logger.info</code> and <code>logger.warn</code> were one array, and a line moved between the two kept the suite green while it made the documented filter wrong. The fake records the pair, and the suite that reads a line asserts the level beside its wording.</p><h2 id="a-defect-found-is-a-defect-filed" tabindex="-1">A defect found is a defect filed <a class="header-anchor" href="#a-defect-found-is-a-defect-filed" aria-label="Permalink to &quot;A defect found is a defect filed&quot;">​</a></h2><p>A defect found while working gets a GitHub issue in the same push, and the record and the documentation name that issue. #233 recorded a real defect in prose and filed nothing; the rework filed #234.</p><p>When one instance of a failure mode is fixed, the other instances are searched for and each is fixed or filed. The standing-fact rule applied to one refusal while a second refusal still wrote about 12 identical lines a minute at the five-second poll. The rule is: do not leave it unmentioned.</p><h2 id="a-number-names-the-head-it-was-taken-at" tabindex="-1">A number names the head it was taken at <a class="header-anchor" href="#a-number-names-the-head-it-was-taken-at" aria-label="Permalink to &quot;A number names the head it was taken at&quot;">​</a></h2><p>Every count in a commit body or a pull request body names the commit it was measured on, and the body is updated after each rework round. A body that keeps the test count of an earlier head, or an acceptance criterion a later ADR retired, is a rule break.</p><p>A branch that carries unrelated churn states in its body which control behavior did not change, so a reader does not read someone else&#39;s rework as this branch&#39;s control decision.</p><h2 id="small-shape-rules" tabindex="-1">Small shape rules <a class="header-anchor" href="#small-shape-rules" aria-label="Permalink to &quot;Small shape rules&quot;">​</a></h2><ul><li>A frame test&#39;s chosen terminal width states the arithmetic that fixes it.</li><li>One copy of a describe block per file. The Work queue pickup suite stood twice in one file, left by an earlier split.</li><li>A wording that has its own test is not restated literally elsewhere. The rewrite Message was spelled out eight times in one shape table, so a wording change turned eight shape records red for a reason that had nothing to do with shape. <code>rewriteCosts()</code> and <code>rewriteMessage()</code> answer the line; the records read them.</li></ul><h2 id="the-reviewer-s-floor" tabindex="-1">The reviewer&#39;s floor <a class="header-anchor" href="#the-reviewer-s-floor" aria-label="Permalink to &quot;The reviewer&#39;s floor&quot;">​</a></h2><p>A review measures the head it reviews, not the description:</p><ul><li><code>bun run lint</code>, <code>bun run typecheck</code>, and one full <code>bun run test</code> on the merged tree, with the machine state recorded.</li><li>Every probe the branch claims is re-run, and each result is reported.</li><li>The score and the specification check name the head they were measured on.</li></ul><h2 id="a-control-change-gets-a-human-look" tabindex="-1">A control change gets a human look <a class="header-anchor" href="#a-control-change-gets-a-human-look" aria-label="Permalink to &quot;A control change gets a human look&quot;">​</a></h2><p>A change under <code>src/components/shared</code> gets <code>bun run gallery</code> opened on the state it changed, and the record says whether anyone looked. The gallery&#39;s examples run inside <code>bun run test</code>, so the automated gate covers the control&#39;s behavior; it covers no pixel, and it claims none.</p><h2 id="what-the-gate-does-not-cover" tabindex="-1">What the gate does not cover <a class="header-anchor" href="#what-the-gate-does-not-cover" aria-label="Permalink to &quot;What the gate does not cover&quot;">​</a></h2><p>The gate is a claim about the automated checks and the tree they ran on. It says nothing about the live terminal walk, the screen-reader path, or the theme inheritance in a real herdr. Those stand open in <a href="https://github.com/SeriousJul/my-little-software-factory/blob/main/docs/verification/quality-gate.md" target="_blank" rel="noreferrer">the verification record</a> and in <a href="https://github.com/SeriousJul/my-little-software-factory/blob/main/docs/verification/shared-controls.md" target="_blank" rel="noreferrer">the shared control record</a>.</p>',48)])])}const m=t(s,[["render",n]]);export{p as __pageData,m as default};
